from typing import List, Tuple
import heapq

def solution() -> Tuple[List[int], int]:
    # Define the graph as an adjacency list (undirected)
    graph = {
        0: [(2, 6), (3, 3)],
        1: [(2, 5), (3, 2)],
        2: [(0, 6), (1, 5), (3, 3)],
        3: [(2, 3), (1, 2), (0, 3)],
    }

    start, target = 0, 3
    # Dijkstra's algorithm
    heap = [(0, start, [start])]  # (cost, node, path)
    visited = set()
    while heap:
        cost, node, path = heapq.heappop(heap)
        if node in visited:
            continue
        visited.add(node)
        if node == target:
            return path, cost
        for neighbor, weight in graph.get(node, []):
            if neighbor not in visited:
                heapq.heappush(heap, (cost + weight, neighbor, path + [neighbor]))
    # If no path found, return empty list and large distance
    return [], float('inf')

