import heapq

def solution() -> Tuple[List[int], int]:
    Find the shortest path from node 0 to node 4 using Dijkstra's algorithm.
    Returns a tuple (path, total_distance).

    # Graph definition (directed)
    graph = {
        0: [(1, 2)],
        1: [(3, 7), (4, 7)],
        2: [(0, 1), (1, 3)],
        3: [(0, 2)],
        4: []
    }

    start, target = 0, 4

    # Initialize distances and predecessor map
    dist = {node: float('inf') for node in graph}
    prev: dict[int, int] = {}
    dist[start] = 0

    # Priority queue for the frontier
    heap: List[Tuple[float, int]] = [(0, start)]

    while heap:
        cur_dist, u = heapq.heappop(heap)
        if cur_dist != dist[u]:
            continue  # stale entry
        if u == target:
            break
        for v, w in graph[u]:
            nd = cur_dist + w
            if nd < dist[v]:
                dist[v] = nd
                prev[v] = u
