        1: [(0, 5), (3, 8), (4, 7)],
        2: [(3, 1), (5, 6)],
        3: [(0, 1), (1, 8), (4, 1), (2, 1)],
        4: [(1, 7), (3, 1)],
        5: [(2, 6)],
    }

    start, target = 0, 5
    # Dijkstra's algorithm
    heap: List[Tuple[int, int]] = [(0, start)]  # (distance, node)
    dist = {node: float('inf') for node in graph}
    prev: dict[int, int] = {}
    dist[start] = 0

    while heap:
        cur_dist, u = heapq.heappop(heap)
        if cur_dist > dist[u]:
            continue
        if u == target:
            break
        for v, w in graph[u]:
            alt = cur_dist + w
            if alt < dist[v]:
