from itertools import permutations
from typing import List, Tuple

def solution() -> Tuple[List[int], int]:
    Solve the TSP for the given 4‑city distance matrix.
    Returns the optimal visiting order (starting at city 0, without the final return to 0)
    and the total distance of the optimal tour.

    # distance matrix (symmetric)
    dist = {
        (0, 1): 78, (0, 2): 42, (0, 3): 129,
        (1, 2): 115, (1, 3): 75,
        (2, 3): 95
    }
    # helper to fetch distance irrespective of order
    def d(i: int, j: int) -> int:
        if i == j:
            return 0
        return dist.get((i, j)) or dist.get((j, i))

    cities = [1, 2, 3]
    best_path: List[int] = []
    best_dist = float('inf')

    for perm in permutations(cities):
        # tour: 0 -> perm -> 0
        tour = (0,) + perm + (0,)
        total = sum(d(tour[k], tour[k + 1]) for k in range(len(tour) - 1))
        if total < best_dist:
            best_dist = total
            best_path = list(tour[:-1])  # omit the final return to 0 for output

    return best_path, int(best_dist)

